-- =====================================================================
--  shop.db  -  a small online store (mock data, generated by src/gen_shop.py)
--  Money is stored as INTEGER kurus (100 kurus = 1 TL), like the course.
-- =====================================================================
PRAGMA foreign_keys = ON;

CREATE TABLE categories (
    id        INTEGER PRIMARY KEY,
    name      TEXT NOT NULL UNIQUE,
    parent_id INTEGER REFERENCES categories(id)        -- NULL = top level
);

CREATE TABLE products (
    id           INTEGER PRIMARY KEY,
    name         TEXT NOT NULL UNIQUE,
    category_id  INTEGER REFERENCES categories(id),    -- a few are NULL (uncategorised)
    price_kurus  INTEGER NOT NULL CHECK (price_kurus > 0),
    stock        INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
    discontinued INTEGER NOT NULL DEFAULT 0 CHECK (discontinued IN (0, 1)),
    added_at     TEXT NOT NULL
);

CREATE TABLE employees (
    id          INTEGER PRIMARY KEY,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    title       TEXT NOT NULL,
    department  TEXT NOT NULL,
    manager_id  INTEGER REFERENCES employees(id),      -- NULL = the boss
    salary_kurus INTEGER NOT NULL,
    hired_at    TEXT NOT NULL
);

CREATE TABLE customers (
    id          INTEGER PRIMARY KEY,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    email       TEXT NOT NULL UNIQUE,
    phone       TEXT,                                  -- may be NULL
    city        TEXT,                                  -- may be NULL
    birth_date  TEXT,                                  -- may be NULL
    joined_at   TEXT NOT NULL,
    referred_by INTEGER REFERENCES customers(id)       -- who invited them (NULL = nobody)
);

CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL REFERENCES customers(id),
    employee_id INTEGER REFERENCES employees(id),      -- sales rep, NULL = self-service web order
    ordered_at  TEXT NOT NULL,
    status      TEXT NOT NULL CHECK (status IN ('pending','shipped','delivered','cancelled','returned')),
    ship_city   TEXT NOT NULL
);

CREATE TABLE order_items (
    order_id         INTEGER NOT NULL REFERENCES orders(id),
    product_id       INTEGER NOT NULL REFERENCES products(id),
    quantity         INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_kurus INTEGER NOT NULL CHECK (unit_price_kurus > 0),  -- price at the time of the order
    PRIMARY KEY (order_id, product_id)
);

CREATE TABLE payments (
    id           INTEGER PRIMARY KEY,
    order_id     INTEGER NOT NULL REFERENCES orders(id),
    amount_kurus INTEGER NOT NULL CHECK (amount_kurus > 0),
    method       TEXT NOT NULL CHECK (method IN ('card','cash','transfer')),
    paid_at      TEXT NOT NULL
);

CREATE TABLE reviews (
    id          INTEGER PRIMARY KEY,
    product_id  INTEGER NOT NULL REFERENCES products(id),
    customer_id INTEGER NOT NULL REFERENCES customers(id),
    rating      INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment     TEXT,
    created_at  TEXT NOT NULL
);











